package server

func init() {
	for name, body := range portalPages {
		pages[name] = body
	}
}

var portalPages = map[string]string{
	"admin_routers": `{{define "content"}}<h1>All routers</h1><table class="table table-striped"><thead><tr><th>Router</th><th>Owner</th><th>Status</th><th>Last seen</th></tr></thead><tbody>{{range .Routers}}<tr><td><a href="/routers/{{.ID}}">{{.DisplayName}}</a></td><td><a href="/profiles/{{.OwnerID}}">View profile</a></td><td>{{if .Paused}}Paused{{else if .Connected}}Connected{{else}}Offline{{end}}</td><td>{{date .LastSeenAt}}</td></tr>{{else}}<tr><td colspan="4">No routers.</td></tr>{{end}}</tbody></table>{{end}}`,
	"portal_dashboard": `{{define "content"}}
<div class="d-flex justify-content-between align-items-center mb-3"><h1>My sna_routers</h1><a class="btn btn-primary" href="/routers/new">Onboard a router</a></div>
{{if not .User.Username}}<div class="alert alert-info">Choose a <a href="/profile/edit">username for your profile</a> so peers can recognize you in the directory.</div>{{end}}
<table class="table table-striped"><thead><tr><th>Router</th><th>Status</th><th>Last seen</th></tr></thead><tbody>
{{range .Routers}}<tr><td><a href="/routers/{{.ID}}">{{.DisplayName}}</a></td><td>{{if .Paused}}Paused{{else if .Connected}}Connected{{else}}Offline{{end}}</td><td>{{date .LastSeenAt}}</td></tr>{{else}}<tr><td colspan="3">No routers onboarded yet.</td></tr>{{end}}
</tbody></table><h2 class="h4 mt-4">My advertised nodes</h2><p class="text-muted">Live exports appear when a router connects and sends a validated snapshot. They are separate from planning records.</p>
<table class="table"><thead><tr><th>Kind</th><th>SNA name</th><th>LLC address / hosting CP</th><th>Router</th></tr></thead><tbody>{{range .Exports}}<tr><td>{{.Kind}}</td><td><code>{{.NetID}}.{{.Name}}</code></td><td>{{template "node_address" .}}</td><td><a href="/routers/{{.RouterID}}">{{.RouterName}}</a></td></tr>{{else}}<tr><td colspan="4">No live advertised nodes.</td></tr>{{end}}</tbody></table>
{{end}}`,
	"router_new":   `{{define "content"}}<div class="col-md-7"><h1>Onboard a sna_router</h1><p>Give this router a name you will recognize. The concentrator assigns its stable internal UUID.</p><form method="post" action="/routers"><input type="hidden" name="csrf" value="{{.CSRF}}"><label class="form-label w-100">Display name<input class="form-control" name="name" maxlength="80" required></label><button class="btn btn-primary">Create router and token</button></form></div>{{end}}`,
	"router_token": `{{define "content"}}<div class="col-lg-8"><h1>{{if .Rotated}}New token for{{else}}Onboarded{{end}} {{.Router.DisplayName}}</h1><div class="alert alert-warning">Copy the bearer token now. Only its hash is stored; it cannot be shown again. A rotation revokes the previous token.</div><table class="table"><tr><th>WebSocket URL</th><td><code>{{.WebSocketURL}}</code></td></tr><tr><th>Bearer token</th><td class="text-break"><code>{{.Token}}</code></td></tr><tr><th>Router display name</th><td>{{.Router.DisplayName}}</td></tr></table><h2 class="h5">Download a router</h2><button class="btn btn-outline-secondary" disabled>Linux amd64 download — coming later</button> <button class="btn btn-outline-secondary" disabled>Linux arm64 download — coming later</button><p class="mt-3"><a class="btn btn-primary" href="/routers/{{.Router.ID}}">View router</a></p></div>{{end}}`,
	"router_details": `{{define "content"}}<div class="d-flex justify-content-between align-items-center"><h1>{{.Router.DisplayName}}</h1><span class="badge {{if .Router.Paused}}text-bg-warning{{else if .Router.Connected}}text-bg-success{{else}}text-bg-secondary{{end}}">{{if .Router.Paused}}Paused{{else if .Router.Connected}}Connected{{else}}Offline{{end}}</span></div><p class="text-muted">Internal ID: <code>{{.Router.ID}}</code> · Last seen: {{date .Router.LastSeenAt}}</p>
<div class="row g-3 mb-4"><div class="col-md-6"><div class="card h-100"><div class="card-body"><h2 class="h5">Configuration</h2><table class="table table-sm"><tr><th>WebSocket URL</th><td><code>{{.WebSocketURL}}</code></td></tr><tr><th>Bearer token</th><td>Hidden after creation; rotate to issue a new one.</td></tr></table><p class="small text-muted">The WebSocket endpoint is active; the router download is coming later.</p><button class="btn btn-outline-secondary btn-sm" disabled>Download router — coming later</button></div></div></div>
<div class="col-md-6"><div class="card h-100"><div class="card-body"><h2 class="h5">Manage router</h2><form method="post" action="/routers/{{.Router.ID}}/rename" class="mb-2"><input type="hidden" name="csrf" value="{{.CSRF}}"><div class="input-group"><input class="form-control" name="name" value="{{.Router.DisplayName}}" maxlength="80" required><button class="btn btn-outline-primary">Rename</button></div></form><form method="post" action="/routers/{{.Router.ID}}/pause" class="d-inline"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="paused" value="{{if .Router.Paused}}0{{else}}1{{end}}"><button class="btn btn-outline-warning">{{if .Router.Paused}}Resume{{else}}Pause{{end}}</button></form> <form method="post" action="/routers/{{.Router.ID}}/rotate" class="d-inline"><input type="hidden" name="csrf" value="{{.CSRF}}"><button class="btn btn-outline-primary">Generate new token</button></form> <form method="post" action="/routers/{{.Router.ID}}/delete" class="d-inline"><input type="hidden" name="csrf" value="{{.CSRF}}"><button class="btn btn-outline-danger">Remove router</button></form></div></div></div></div>
<form method="post" action="/routers/{{.Router.ID}}/llc-facing" class="card card-body mb-4"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="enabled" value="{{if .Router.LLCFacing}}0{{else}}1{{end}}"><div><strong>Local LLC-facing router:</strong> {{if .Router.LLCFacing}}Enabled{{else}}Disabled{{end}}. Only enabled routers may receive authorized managed CP bindings. <button class="btn btn-outline-primary btn-sm">{{if .Router.LLCFacing}}Disable{{else}}Enable{{end}}</button></div></form>
<h2 class="h4">Advertised nodes</h2><table class="table"><thead><tr><th>Kind</th><th>SNA name</th><th>LLC address / hosting CP</th><th>Route generation</th></tr></thead><tbody>{{range .Exports}}<tr><td>{{.Kind}}</td><td><code>{{.NetID}}.{{.Name}}</code></td><td>{{template "node_address" .}}</td><td>{{.Generation}}</td></tr>{{else}}<tr><td colspan="4">No live advertisements.</td></tr>{{end}}</tbody></table>
<h2 class="h4 mt-4">Router diagnostics</h2><p class="text-muted">Decoded event summaries, errors and source IPs will be recorded here once transport is active. The latest 100 records are shown; records expire after 30 days.</p><form method="get" class="mb-3"><div class="input-group"><input class="form-control" name="q" value="{{.Search}}" placeholder="Search event, node, summary or IP"><button class="btn btn-outline-primary">Search</button></div></form><table class="table table-sm table-striped"><thead><tr><th>Time (UTC)</th><th>Direction</th><th>Level</th><th>Event / decoded data</th><th>Source IP</th><th>Peer</th></tr></thead><tbody>{{range .Logs}}<tr><td>{{date .OccurredAt}}</td><td>{{.Direction}}</td><td>{{.Level}}</td><td><strong>{{.EventType}}</strong>: {{.Summary}}{{if .DetailsJSON}}<details><summary>Fields</summary><pre class="text-wrap">{{.DetailsJSON}}</pre></details>{{end}}</td><td><code>{{.SourceIP}}</code></td><td>{{if .PeerUserID}}<a href="/profiles/{{.PeerUserID}}">View peer</a>{{end}}</td></tr>{{else}}<tr><td colspan="6">No matching logs.</td></tr>{{end}}</tbody></table>{{end}}`,
	"global_directory": `{{define "content"}}<h1>Global directory</h1><p>Live CP and LU exports from all connected routers. Select an owner to view their profile and block them if needed.</p><table class="table table-striped"><thead><tr><th>Kind</th><th>SNA name</th><th>LLC address / hosting CP</th><th>Router</th><th>Owner</th></tr></thead><tbody>{{range .Exports}}<tr><td>{{.Kind}}</td><td><code>{{.NetID}}.{{.Name}}</code></td><td>{{template "node_address" .}}</td><td>{{.RouterName}}</td><td><a href="/profiles/{{.OwnerID}}">{{if .OwnerUsername}}{{.OwnerUsername}}{{else}}View profile{{end}}</a></td></tr>{{else}}<tr><td colspan="5">No live advertised nodes yet.</td></tr>{{end}}</tbody></table>{{end}}`,
	"flows":            `{{define "content"}}<h1>Flows</h1><p class="text-muted">{{if .All}}Recent flow records across all users.{{else}}Recent flow records for your routers.{{end}}</p><form method="get" class="mb-3"><div class="input-group"><input class="form-control" type="search" name="q" value="{{.Search}}" placeholder="Search event, node, summary or source IP"><button class="btn btn-outline-primary">Search</button></div></form><div class="table-responsive"><table class="table table-sm table-striped"><thead><tr><th>Time (UTC)</th>{{if .All}}<th>Owner</th>{{end}}<th>Direction</th><th>Router</th><th>Peer</th><th>Event</th><th>Source IP</th></tr></thead><tbody>{{range .Logs}}<tr><td>{{date .OccurredAt}}</td>{{if $.All}}<td><a href="/profiles/{{.OwnerID}}">View owner</a></td>{{end}}<td>{{.Direction}}</td><td><a href="/routers/{{.RouterID}}">View router</a></td><td>{{if .PeerUserID}}<a href="/profiles/{{.PeerUserID}}">View peer</a>{{end}}</td><td><strong>{{.EventType}}</strong>: {{.Summary}}{{if .DetailsJSON}}<details><summary>Fields</summary><pre class="text-wrap">{{.DetailsJSON}}</pre></details>{{end}}</td><td><code>{{.SourceIP}}</code></td></tr>{{else}}<tr><td colspan="{{if .All}}7{{else}}6{{end}}">No matching flows.</td></tr>{{end}}</tbody></table></div>{{end}}`,
	"profile_edit":     `{{define "content"}}<div class="col-lg-8"><h1>Edit profile</h1><form method="post" action="/profile/edit"><input type="hidden" name="csrf" value="{{.CSRF}}"><label class="form-label w-100">Username (3–32 letters, digits, underscores or hyphens)<input class="form-control" name="username" value="{{.User.Username}}" required></label><div class="row"><div class="col"><label class="form-label w-100">First name (optional)<input class="form-control" name="first_name" value="{{.User.FirstName}}" maxlength="80"></label></div><div class="col"><label class="form-label w-100">Last name (optional)<input class="form-control" name="last_name" value="{{.User.LastName}}" maxlength="80"></label></div></div><label class="form-check-label"><input class="form-check-input" type="checkbox" name="public_email" value="1" {{if .User.PublicEmail}}checked{{end}}> Show my email address on my public profile</label><div><button class="btn btn-primary mt-3">Save profile</button></div></form><hr><h2 class="h5">Profile picture (optional)</h2><p>PNG or JPEG, up to 256 KiB and 2048 × 2048 pixels.</p><form method="post" action="/profile/picture" enctype="multipart/form-data"><input type="hidden" name="csrf" value="{{.CSRF}}"><input class="form-control" type="file" name="picture" accept="image/png,image/jpeg" required><button class="btn btn-outline-primary mt-2">Upload picture</button></form><form method="post" action="/profile/picture/delete" class="mt-2"><input type="hidden" name="csrf" value="{{.CSRF}}"><button class="btn btn-outline-danger">Remove picture</button></form></div>{{end}}`,
	"profile_view":     `{{define "content"}}<div class="col-lg-8"><div class="d-flex align-items-center gap-3 mb-3">{{if .HasPicture}}<img src="/profiles/{{.Profile.ID}}/picture" alt="Profile picture" width="96" height="96" class="rounded-circle object-fit-cover">{{end}}<div><h1 class="mb-0">{{if .Profile.Username}}{{.Profile.Username}}{{else}}Snusnu user{{end}}</h1>{{if or .Profile.FirstName .Profile.LastName}}<p class="mb-0">{{.Profile.FirstName}} {{.Profile.LastName}}</p>{{end}}</div></div>{{if .ShowEmail}}<p>Email: <a href="mailto:{{.Profile.Email}}">{{.Profile.Email}}</a></p>{{end}}{{if .Own}}<a class="btn btn-outline-primary" href="/profile/edit">Edit profile</a>{{else}}<form method="post" action="/profiles/{{.Profile.ID}}/block"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="blocked" value="{{if .Blocked}}0{{else}}1{{end}}"><button class="btn {{if .Blocked}}btn-outline-success{{else}}btn-outline-danger{{end}}">{{if .Blocked}}Unblock data from this user{{else}}Block data from this user{{end}}</button></form>{{end}}{{if eq .User.Role "admin"}}<form method="post" action="/admin/users/reset-password" class="mt-2"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="id" value="{{.Profile.ID}}"><button class="btn btn-outline-danger btn-sm">Reset this user's password</button></form>{{end}}<h2 class="h4 mt-4">Advertised nodes</h2><table class="table"><thead><tr><th>Kind</th><th>SNA name</th><th>Router</th></tr></thead><tbody>{{range .Exports}}<tr><td>{{.Kind}}</td><td><code>{{.NetID}}.{{.Name}}</code></td><td>{{.RouterName}}</td></tr>{{else}}<tr><td colspan="3">No live advertised nodes.</td></tr>{{end}}</tbody></table></div>{{end}}`,
}
